Tool response:
Tool: add_clause_to_draft
Description: Inserts a clause into a draft contract at the specified position.
The clause is identified by its title and jurisdiction, and the draft is identified by its ID.
The version_id must also be provided to ensure correct versioning.
Optional fields risk_level and last_reviewed can be included to fully specify the clause.
Parameters:
    {
      "type": "object",
      "properties": {
        "draft_id": {
          "type": "string",
          "title": "Draft Id",
          "description": ""
        },
        "version_id": {
          "type": "string",
          "description": "The version identifier for the draft",
          "title": "Version Id"
        },
        "clause_title": {
          "type": "string",
          "title": "Clause Title",
          "description": "The title of the clause to be added"
        },
        "jurisdiction": {
          "type": "string",
          "title": "Jurisdiction",
          "description": "The jurisdiction associated with the clause"
        },
        "risk_level": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Risk Level",
          "description": "The risk level of the clause (low, medium, high, critical)"
        },
        "last_reviewed": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Last Reviewed",
          "description": "The date the clause was last reviewed (YYYY-MM-DD)"
        },
        "position": {
          "type": "integer",
          "title": "Position",
          "description": "The position where the clause should be inserted in the draft"
        }
      },
      "required": [
        "draft_id",
        "version_id"
      ]
    }
